		if (taken.has(entry)) continue;
		const free = blocks.filter((item) => item.kind === entry.kind && !entryOf.has(item));
		const node = free.find((item) => item.id === `block-${item.kind}`) ?? free[0];
		if (node) {
			entryOf.set(node, entry);
			taken.add(entry);
		}
