	const demoLabel = base.layout.blocks.map((node) => node.copy?.badge).find(Boolean) ?? demoLabelForLocale(ctx.demoLabel, base.locale) ?? defaultDemoLabel(base.locale);
	const english = base.locale.toLowerCase().split("-")[0] === "en";

